/**
 * TIME IS CAPITAL / Clockwork Typography.
 * Original asset-free Canvas 2D. Four scenes; seamless 20-second loop.
 * Time is in SECONDS. Call draw(ctx,time,width,height) for each frame.
 * Encoding target: 3840 x 2160, 60 fps, 100,000,000 bits/second CBR.
 * The host encoder must enforce the bitrate; Canvas renders frames only.
 */
const EXPORT_SETTINGS=Object.freeze({
  width:3840,height:2160,fps:60,duration:20,
  bitrate:100000000,minBitrate:100000000,maxBitrate:100000000
});

const TimeIsCapital=(()=>{
  'use strict';
  const TAU=Math.PI*2;
  const C={bg:'#123C70',gold:'#EDC46A',ink:'#F2F5FC',muted:'#A9BED7',line:'#42658C'};
  const FAMILY='"Liberation Sans", Arial, Helvetica, sans-serif';
  const clamp=x=>Math.max(0,Math.min(1,x)),frac=x=>x-Math.floor(x);
  const ease=x=>{x=clamp(x);return x*x*x*(x*(6*x-15)+10);};
  const ramp=(a,b,x)=>ease((x-a)/(b-a));
  const cache=new Map();
  function measure(ctx,str,size,weight=700){
    const key=str+'|'+size+'|'+weight;if(cache.has(key))return cache.get(key);
    ctx.font=weight+' '+size+'px '+FAMILY;ctx.textBaseline='alphabetic';
    const m=ctx.measureText(str),result={width:m.width,ascent:m.actualBoundingBoxAscent||size*.73};
    if(cache.size>128)cache.clear();cache.set(key,result);return result;
  }
  function label(ctx,str,x,y,size=16,color=C.muted,align='left',weight=500){
    ctx.font=weight+' '+size+'px '+FAMILY;ctx.textAlign=align;ctx.textBaseline='middle';
    ctx.fillStyle=color;ctx.fillText(str,x,y);
  }
  function tracked(ctx,str,x,y,size,color,spacing=2){
    ctx.font='600 '+size+'px '+FAMILY;ctx.textAlign='left';ctx.textBaseline='middle';ctx.fillStyle=color;
    for(const ch of str){ctx.fillText(ch,x,y);x+=ctx.measureText(ch).width+spacing;}
  }
  function line(ctx,x1,y1,x2,y2,color=C.line,width=1.5){
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();
  }
  function word(ctx,str,cx,cy,size,tracking,alpha,color,outline=false){
    if(alpha<.00001)return;
    const chars=Array.from(str),widths=chars.map(ch=>measure(ctx,ch,size).width);
    const total=widths.reduce((a,b)=>a+b,0)+tracking*(chars.length-1),ascent=measure(ctx,str,size).ascent;
    let x=cx-total/2;
    ctx.save();ctx.globalAlpha=alpha;ctx.font='700 '+size+'px '+FAMILY;
    ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle=color;ctx.strokeStyle=color;ctx.lineWidth=1.5;
    for(let i=0;i<chars.length;i++){
      if(outline)ctx.strokeText(chars[i],x,cy+ascent/2);else ctx.fillText(chars[i],x,cy+ascent/2);
      x+=widths[i]+tracking;
    }
    ctx.restore();
  }
  function headline(ctx,index,seconds){
    const closing=index===3;
    const settle=closing?1-ramp(.85,4.20,seconds):ramp(.12,2.20,seconds);
    const tracking=1+17*(1-settle);
    const alpha=ramp(.05,.86,seconds)*(1-ramp(closing?2.95:4.08,closing?4.72:4.95,seconds));
    const ghost=index===0?.18*(1-ramp(0,.75,seconds)):closing?.18*ramp(4.12,4.98,seconds):0;
    if(ghost>0)word(ctx,'TIME',650,441,190,18,ghost,C.ink,true);
    if(index===2){
      word(ctx,'TIME IS',650,354,116,tracking*.65,alpha,C.ink);
      word(ctx,'CAPITAL',650,552,134,tracking*.65,alpha,C.gold);
    }else word(ctx,index===1?'FOCUS':'TIME',650,441,index===1?168:190,tracking,alpha,index===1?C.gold:C.ink);
    const captions=['MAKE EVERY INTERVAL COUNT','GIVE PRIORITY YOUR ATTENTION',
      'TIME CREATES ROOM FOR VALUE','RETURN WITH A CLEARER PURPOSE'];
    ctx.save();ctx.globalAlpha=ramp(.35,1.22,seconds)*(1-ramp(4.03,4.95,seconds));
    tracked(ctx,captions[index],148,684,16,C.muted,1.5);ctx.restore();
    line(ctx,148,286,1152,286,C.line,1.2);line(ctx,148,633,1152,633,C.line,1.2);
    ctx.fillStyle=C.gold;ctx.fillRect(148,284,48,4);ctx.fillRect(1104,631,48,4);
  }
  function arc(ctx,cx,cy,r,start,end,color,width=1.5){
    ctx.beginPath();ctx.arc(cx,cy,r,start,end);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();
  }
  function orbitalLabel(ctx,str,cx,cy,r,angle){
    const size=12,spacing=2,chars=Array.from(str);
    const widths=chars.map(ch=>measure(ctx,ch,size,600).width);
    let cursor=-(widths.reduce((a,b)=>a+b,0)+spacing*(chars.length-1))/2;
    for(let i=0;i<chars.length;i++){
      const theta=angle+(cursor+widths[i]/2)/r;
      ctx.save();ctx.translate(cx+r*Math.cos(theta),cy+r*Math.sin(theta));ctx.rotate(theta+Math.PI/2);
      label(ctx,chars[i],0,0,size,C.ink,'center',600);ctx.restore();
      cursor+=widths[i]+spacing;
    }
  }
  function clockwork(ctx,phase){
    const cx=1512,cy=451;
    for(let i=0;i<48;i++){
      const theta=-Math.PI/2+TAU*i/48,inner=i%4===0?176:182;
      line(ctx,cx+inner*Math.cos(theta),cy+inner*Math.sin(theta),
        cx+190*Math.cos(theta),cy+190*Math.sin(theta),i%4===0?C.ink:C.line,i%4===0?2:1.3);
    }
    arc(ctx,cx,cy,165,0,TAU,C.line,1.2);
    arc(ctx,cx,cy,124,0,TAU,C.line,1.2);
    arc(ctx,cx,cy,88,0,TAU,C.line,1.2);
    const outer=-Math.PI/2+TAU*phase,sweep=TAU*(.32+.065*Math.cos(TAU*phase));
    ctx.save();ctx.lineCap='round';arc(ctx,cx,cy,151,outer-sweep,outer,C.gold,6);ctx.restore();
    ctx.fillStyle=C.gold;ctx.beginPath();ctx.arc(cx+151*Math.cos(outer),cy+151*Math.sin(outer),4.5,0,TAU);ctx.fill();
    const inner=Math.PI/3-TAU*phase*2;
    ctx.save();ctx.lineCap='round';arc(ctx,cx,cy,112,inner-TAU*.21,inner,C.ink,4);ctx.restore();
    ctx.fillStyle=C.ink;ctx.beginPath();ctx.arc(cx+112*Math.cos(inner),cy+112*Math.sin(inner),3.5,0,TAU);ctx.fill();
    for(let i=0;i<3;i++)orbitalLabel(ctx,['TIME','FOCUS','VALUE'][i],cx,cy,214,outer+TAU*i/3);
    word(ctx,'VALUE',cx,437,36,1,1,C.ink);
    label(ctx,'OF TIME',cx,483,12,C.muted,'center',600);
    label(ctx,'EVERY INTERVAL MATTERS',cx,711,13,C.gold,'center',600);
  }
  function intervals(ctx,phase){
    const titles=['ALLOCATE','FOCUS','COMPOUND'];
    const captions=['PROTECT THE PRIORITY','GIVE EACH INTERVAL A ROLE','LET CONSISTENCY ADD VALUE'];
    for(let i=0;i<3;i++){
      const x=148+556*i;tracked(ctx,titles[i],x,777,17,C.ink,1.8);
      line(ctx,x,804,x+512,804,C.line,1.2);
      line(ctx,x+5,850,x+475,850,C.line,1.3);
      for(let j=0;j<11;j++){
        const xx=x+10+j*46;
        line(ctx,xx,j%2===0?831:838,xx,857,j%2===0?C.muted:C.line,j%2===0?1.8:1.2);
      }
      const u=frac(phase*(i===1?2:1)+i/3),fade=ramp(0,.08,u)*(1-ramp(.92,1,u));
      const xx=x+10+460*u;
      ctx.save();ctx.globalAlpha=fade;ctx.fillStyle=C.gold;
      ctx.beginPath();ctx.moveTo(xx-6,813);ctx.lineTo(xx+6,813);ctx.lineTo(xx,824);ctx.closePath();ctx.fill();ctx.restore();
      label(ctx,captions[i],x,903,13,C.muted);
    }
  }
  function frame(ctx,phase){
    tracked(ctx,'TIME IS CAPITAL',112,103,21,C.ink,3.1);
    label(ctx,'TIME / FOCUS / CONTINUITY',1808,103,16,C.muted,'right');
    line(ctx,112,158,1808,158,C.line,1.5);ctx.fillStyle=C.gold;ctx.fillRect(112,156,84,4);
    label(ctx,'CLEAR PRIORITIES. PURPOSEFUL INTERVALS.',148,222,15,C.gold);
    line(ctx,112,947,1808,947,C.line,1.5);
    const names=['TIME','FOCUS','CAPITAL','RETURN'];
    for(let i=0;i<4;i++){
      const x=112+i*432,p=Math.pow(.5+.5*Math.cos(TAU*(phase-i/4)),2);
      label(ctx,names[i],x,982,14,C.muted);
      line(ctx,x,1009,x+382,1009,C.line,2);line(ctx,x,1009,x+50+212*p,1009,C.gold,3);
    }
    label(ctx,'MAKE ROOM FOR WHAT MATTERS',112,1048,13,C.muted);
    for(let i=0;i<7;i++){
      ctx.save();ctx.globalAlpha=.25+.75*(.5+.5*Math.cos(TAU*(phase-i/7)));
      ctx.fillStyle=C.gold;ctx.fillRect(1678+i*20,1045,5,5);ctx.restore();
    }
  }
  function render(ctx,loopT,currentScene,sceneProgress){
    const phase=loopT/20,seconds=sceneProgress*5;
    headline(ctx,currentScene,seconds);clockwork(ctx,phase);intervals(ctx,phase);frame(ctx,phase);
  }
  return {render,background:C.bg};
})();

function draw(ctx,time,width,height){
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width,height);
  if(!(minSide>0)||!Number.isFinite(t))return;
  ctx.save();ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowColor='rgba(0,0,0,0)';ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;
  ctx.lineCap='butt';ctx.lineJoin='miter';ctx.miterLimit=4;ctx.setLineDash([]);ctx.lineDashOffset=0;
  ctx.fillStyle=TimeIsCapital.background;ctx.fillRect(0,0,width,height);
  const scale=minSide/1080;
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);
  TimeIsCapital.render(ctx,loopT,currentScene,sceneProgress);
  ctx.restore();
}

/**
 * ECONOMY IN MOTION / Interconnected Typographic Mosaic.
 * Original asset-free Canvas 2D. Four scenes; seamless 20-second loop.
 * Time is in SECONDS. Call draw(ctx,time,width,height) for each frame.
 * Encoding target: 3840 x 2160, 60 fps, 100,000,000 bits/second CBR.
 * The host encoder must enforce the bitrate; Canvas renders frames only.
 */
const EXPORT_SETTINGS=Object.freeze({
  width:3840,height:2160,fps:60,duration:20,
  bitrate:100000000,minBitrate:100000000,maxBitrate:100000000
});

const EconomyInMotion=(()=>{
  'use strict';
  const TAU=Math.PI*2;
  const C={bg:'#D5F0EB',violet:'#6C42CF',ink:'#153B46',muted:'#66857F',line:'#A6CEC5'};
  const FAMILY='"Liberation Sans", Arial, Helvetica, sans-serif';
  const clamp=x=>Math.max(0,Math.min(1,x));
  const ease=x=>{x=clamp(x);return x*x*x*(x*(6*x-15)+10);};
  const ramp=(a,b,x)=>ease((x-a)/(b-a));
  const mix=(a,b,p)=>a+(b-a)*p;
  const cache=new Map();
  function measure(ctx,str,size,weight=700){
    const key=str+'|'+size+'|'+weight;if(cache.has(key))return cache.get(key);
    ctx.font=weight+' '+size+'px '+FAMILY;ctx.textBaseline='alphabetic';
    const m=ctx.measureText(str),result={width:m.width,ascent:m.actualBoundingBoxAscent||size*.73};
    if(cache.size>320)cache.clear();cache.set(key,result);return result;
  }
  function label(ctx,str,x,y,size=16,color=C.muted,align='left',weight=500){
    ctx.font=weight+' '+size+'px '+FAMILY;ctx.textAlign=align;ctx.textBaseline='middle';
    ctx.fillStyle=color;ctx.fillText(str,x,y);
  }
  function tracked(ctx,str,x,y,size,color,spacing=2){
    ctx.font='600 '+size+'px '+FAMILY;ctx.textAlign='left';ctx.textBaseline='middle';ctx.fillStyle=color;
    for(const ch of str){ctx.fillText(ch,x,y);x+=ctx.measureText(ch).width+spacing;}
  }
  function line(ctx,x1,y1,x2,y2,color=C.line,width=1.5){
    ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke();
  }
  function fittedWord(ctx,str,cx,cy,size,tracking,maxWidth,maxHeight,color,alpha){
    if(alpha<.00001)return;
    const chars=Array.from(str);
    let widths=chars.map(ch=>measure(ctx,ch,size).width);
    let ascent=measure(ctx,str,size).ascent;
    const initial=widths.reduce((a,b)=>a+b,0)+tracking*(chars.length-1);
    const fit=Math.min(1,maxWidth/initial,maxHeight/ascent);
    size*=fit;tracking*=fit;
    widths=chars.map(ch=>measure(ctx,ch,size).width);ascent=measure(ctx,str,size).ascent;
    const width=widths.reduce((a,b)=>a+b,0)+tracking*(chars.length-1);let x=cx-width/2;
    ctx.save();ctx.globalAlpha=alpha;ctx.font='700 '+size+'px '+FAMILY;
    ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle=color;
    for(let i=0;i<chars.length;i++){
      ctx.fillText(chars[i],x,cy+ascent/2);x+=widths[i]+tracking;
    }
    ctx.restore();
  }
  function boundaries(index,seconds,phase){
    const opening=[.50,.50,.50],shifted=[.60,.40,.45],hero=[.76,.24,.50];
    let a=opening,b=opening,p=0;
    if(index===1){
      if(seconds<2.4){a=opening;b=shifted;p=ramp(.12,2.4,seconds);}
      else{a=shifted;b=hero;p=ramp(2.4,4.88,seconds);}
    }else if(index===2){a=hero;b=hero;}
    else if(index===3){a=hero;b=opening;p=ramp(.18,4.82,seconds);}
    const top=mix(a[0],b[0],p)+.012*Math.sin(TAU*phase);
    const bottom=mix(a[1],b[1],p)-.012*Math.sin(TAU*phase);
    const row=mix(a[2],b[2],p)+.009*Math.sin(TAU*phase*2);
    const x=148,y=252,w=1624,h=640,gap=20,usableW=w-gap,usableH=h-gap;
    const ht=usableH*row,hb=usableH-ht,wt=usableW*top,wb=usableW*bottom;
    // Shared split coordinates guarantee a constant, open gutter at every
    // intermediate frame. Each row is an independent pair of aligned panels.
    return [{x,y,w:wt,h:ht},{x:x+wt+gap,y,w:usableW-wt,h:ht},
      {x,y:y+ht+gap,w:wb,h:hb},{x:x+wb+gap,y:y+ht+gap,w:usableW-wb,h:hb}];
  }
  function systemMotif(ctx,p,phase,alpha){
    const cx=p.x+p.w/2,cy=p.y+p.h*.48;
    const widths=[.45,.71,.91,.61],left=cx-98;
    ctx.save();ctx.globalAlpha=alpha;
    for(let i=0;i<4;i++){
      const width=116*widths[i]+22*(.5+.5*Math.cos(TAU*(phase*2-i/4)));
      ctx.fillStyle=i%2===0?C.ink:C.violet;ctx.fillRect(left,cy-47+i*26,width,12);
      ctx.fillStyle=C.violet;ctx.fillRect(cx+79,cy-47+i*26,12,12);
    }
    ctx.restore();
  }
  function panel(ctx,p,i,index,seconds,phase){
    const light=i===2,fg=light?C.ink:C.bg,quiet=light?C.muted:C.bg;
    ctx.fillStyle=i===1?C.violet:light?C.bg:C.ink;ctx.fillRect(p.x,p.y,p.w,p.h);
    if(light){ctx.strokeStyle=C.ink;ctx.lineWidth=1.5;ctx.strokeRect(p.x+.75,p.y+.75,p.w-1.5,p.h-1.5);}
    label(ctx,'0'+(i+1),p.x+36,p.y+35,12,fg,'left',600);
    for(let a=0;a<2;a++)for(let b=0;b<2;b++){
      ctx.save();ctx.globalAlpha=.36+.64*(.5+.5*Math.cos(TAU*(phase-(a+b)/4-i/4)));
      ctx.fillStyle=fg;ctx.fillRect(p.x+p.w-63+a*12,p.y+28+b*12,7,7);ctx.restore();
    }
    let alpha=1;
    if(index===1)alpha=1-ramp(4.05,4.95,seconds);
    else if(index===2)alpha=ramp(.08,.95,seconds)*(1-ramp(4.05,4.95,seconds));
    else if(index===3)alpha=ramp(.08,.95,seconds);
    const hero=index===2;
    const nouns=['DEMAND','TRADE','CAPITAL','PRODUCTION'];
    const words=hero?['ECONOMY','IN','','MOTION']:nouns;
    const sizes=hero?[142,122,100,142]:[98,110,100,92];
    const tracking=1+1.5*(.5+.5*Math.cos(TAU*(phase*2-i/4)))
      +(hero?5*(1-ramp(.12,2.35,seconds)):0);
    // The generous inner box is a safety mask; text is fitted before drawing.
    ctx.save();ctx.beginPath();ctx.rect(p.x+28,p.y+64,p.w-56,p.h-154);ctx.clip();
    if(hero&&i===2)systemMotif(ctx,p,phase,alpha);
    else fittedWord(ctx,words[i],p.x+p.w/2,p.y+p.h*.46,sizes[i],tracking,p.w-88,
      p.h*.32,fg,alpha);
    ctx.restore();
    const captions=hero?['INDIVIDUAL MARKETS. SHARED MOMENTUM.','THROUGH CONNECTION',
      'ONE CONNECTED SYSTEM','VALUE MOVES THROUGH CONNECTION']:
      ['DEMAND CREATES DIRECTION','TRADE CONNECTS MARKETS','CAPITAL ENABLES PROGRESS','PRODUCTION ADDS VALUE'];
    ctx.save();ctx.globalAlpha=alpha;
    label(ctx,captions[i],p.x+36,p.y+p.h-82,12,quiet);
    ctx.restore();
    ctx.save();ctx.globalAlpha=.30;line(ctx,p.x+36,p.y+p.h-48,p.x+p.w-36,p.y+p.h-48,fg,1.2);ctx.restore();
    const span=p.w-72,progress=.25+.42*(.5+.5*Math.cos(TAU*(phase-i/4)));
    line(ctx,p.x+36,p.y+p.h-48,p.x+36+span*progress,p.y+p.h-48,fg,2.5);
  }
  function crossPanelRoutes(ctx,panels,phase){
    // These routes occupy an empty strip below each panel's progress track.
    // Their short bridges cross only the deliberately reserved gutters.
    for(let row=0;row<2;row++){
      const a=panels[row*2],b=panels[row*2+1],y=a.y+a.h-24;
      const alpha=.42+.28*(.5+.5*Math.cos(TAU*(phase*2-row/2)));
      ctx.save();ctx.globalAlpha=alpha;
      line(ctx,a.x+36,y,a.x+a.w,y,row===0?C.bg:C.ink,1.2);
      line(ctx,a.x+a.w,y,b.x,y,C.violet,1.8);
      line(ctx,b.x,y,b.x+b.w-36,y,C.bg,1.2);ctx.restore();
    }
  }
  function frame(ctx,phase){
    tracked(ctx,'ECONOMY IN MOTION',112,103,21,C.ink,3.1);
    label(ctx,'DEMAND / TRADE / CAPITAL / PRODUCTION',1808,103,16,C.muted,'right');
    line(ctx,112,158,1808,158,C.line,1.5);ctx.fillStyle=C.violet;ctx.fillRect(112,156,84,4);
    label(ctx,'INDIVIDUAL MARKETS. ONE CONNECTED ECONOMY.',148,221,15,C.violet);
    label(ctx,'CONNECTION CREATES MOMENTUM',148,923,13,C.muted);
    line(ctx,112,951,1808,951,C.line,1.5);
    const names=['DEMAND','TRADE','CAPITAL','PRODUCTION'];
    for(let i=0;i<4;i++){
      const x=112+i*432,p=Math.pow(.5+.5*Math.cos(TAU*(phase-i/4)),2);
      label(ctx,names[i],x,985,14,C.muted);
      line(ctx,x,1012,x+382,1012,C.line,2);line(ctx,x,1012,x+50+212*p,1012,C.violet,3);
    }
    label(ctx,'A CONNECTED SYSTEM OF VALUE',112,1049,13,C.muted);
    for(let i=0;i<7;i++){
      ctx.save();ctx.globalAlpha=.25+.75*(.5+.5*Math.cos(TAU*(phase-i/7)));
      ctx.fillStyle=C.violet;ctx.fillRect(1678+i*20,1046,5,5);ctx.restore();
    }
  }
  function render(ctx,loopT,currentScene,sceneProgress){
    const phase=loopT/20,seconds=sceneProgress*5,panels=boundaries(currentScene,seconds,phase);
    for(let i=0;i<4;i++)panel(ctx,panels[i],i,currentScene,seconds,phase);
    crossPanelRoutes(ctx,panels,phase);frame(ctx,phase);
  }
  return {render,background:C.bg};
})();

function draw(ctx,time,width,height){
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width,height);
  if(!(minSide>0)||!Number.isFinite(t))return;
  ctx.save();ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowColor='rgba(0,0,0,0)';ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;
  ctx.lineCap='butt';ctx.lineJoin='miter';ctx.miterLimit=4;ctx.setLineDash([]);ctx.lineDashOffset=0;
  ctx.fillStyle=EconomyInMotion.background;ctx.fillRect(0,0,width,height);
  const scale=minSide/1080;
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);
  EconomyInMotion.render(ctx,loopT,currentScene,sceneProgress);
  ctx.restore();
}

/**
 * DIGITAL FINANCE SIGNAL / Segmented Type Transmission.
 * Original asset-free Canvas 2D. Four scenes, a seamless 20-second loop.
 * Time is in SECONDS; call draw(ctx,time,width,height) for each frame.
 * Encoding target: 3840 x 2160, 60 fps, 100,000,000 bits/second CBR.
 * The host encoder must enforce the bitrate; Canvas renders frames only.
 */
const EXPORT_SETTINGS=Object.freeze({
  width:3840,height:2160,fps:60,duration:20,
  bitrate:100000000,minBitrate:100000000,maxBitrate:100000000
});

const DigitalFinanceSignal=(()=>{
  'use strict';
  const TAU=2*Math.PI;
  const C={bg:'#160F33',mint:'#58FFD2',violet:'#A18AFF',muted:'#A89EC7',line:'#3B315C'};
  const FAMILY='"Liberation Sans", Arial, Helvetica, sans-serif';
  const clamp=x=>Math.max(0,Math.min(1,x)),frac=x=>x-Math.floor(x);
