function draw(ctx,time,width,height){
  const t = time;
  const duration = 20;
  const sceneCount = 4;
  const loopT = ((t % duration) + duration) % duration;
  const sceneDuration = duration / sceneCount;
  const currentScene = Math.floor(loopT / sceneDuration);
  const sceneProgress = (loopT % sceneDuration) / sceneDuration;
  const minSide = Math.min(width,height);
  if(!(minSide>0)||!Number.isFinite(t))return;
  ctx.save();ctx.globalAlpha=1;ctx.globalCompositeOperation='source-over';
  ctx.shadowColor='rgba(0,0,0,0)';ctx.shadowBlur=0;ctx.shadowOffsetX=0;ctx.shadowOffsetY=0;
  ctx.lineCap='butt';ctx.lineJoin='miter';ctx.miterLimit=4;ctx.setLineDash([]);ctx.lineDashOffset=0;
  ctx.fillStyle=GlobalExchange.background;ctx.fillRect(0,0,width,height);
  const scale=minSide/1080;
  ctx.translate(width/2,height/2);ctx.scale(scale,scale);ctx.translate(-960,-540);
  GlobalExchange.render(ctx,loopT,currentScene,sceneProgress);
  ctx.restore();
}

/**
 * PRECISION ACCOUNTING / rolling numbers and editorial ledger typography.
 * Original, asset-free Canvas 2D. 20 seconds, four scenes, seamless.
 * Public frame renderer: draw(ctx, timeInSeconds, width, height).
 * Target encoding: 3840 x 2160, 60 fps, 100,000,000 bits/second CBR.
 * The host encoder must enforce bitrate; Canvas renders frames only.
 */
const EXPORT_SETTINGS=Object.freeze({
  width:3840,height:2160,fps:60,duration:20,
  bitrate:100000000,minBitrate:100000000,maxBitrate:100000000
});

const PrecisionAccounting=(()=>{
  'use strict';
  const TAU=Math.PI*2;
  const C={bg:'#EAE7E1',ink:'#29303E',blue:'#2786B8',muted:'#6F7C87',line:'#BEC5C9',panel:'#F4F1EB'};
  const FAMILY='"Liberation Sans", Arial, Helvetica, sans-serif';
  const MONO='"DejaVu Sans Mono", "Liberation Mono", "Courier New", monospace';
  const cache=new Map();
  const clamp=x=>Math.max(0,Math.min(1,x));
  const ease=x=>{x=clamp(x);return x*x*x*(x*(x*6-15)+10);};
  const ramp=(a,b,x)=>ease((x-a)/(b-a));
  const frac=x=>x-Math.floor(x);
  function metrics(ctx,str,size,weight=700,family=FAMILY){
    const key=str+'|'+size+'|'+weight+'|'+family;if(cache.has(key))return cache.get(key);
    ctx.font=weight+' '+size+'px '+family;ctx.textBaseline='alphabetic';
    const m=ctx.measureText(str),r={width:m.width,ascent:m.actualBoundingBoxAscent||size*.74,
      descent:Math.max(0,m.actualBoundingBoxDescent||0),size};
    if(cache.size>160)cache.clear();cache.set(key,r);return r;
  }
  function label(ctx,str,x,y,size=16,color=C.muted,align='left',weight=500){
    ctx.font=weight+' '+size+'px '+FAMILY;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillStyle=color;
    ctx.fillText(str,x,y);
  }
  function tracked(ctx,str,x,y,size,color,spacing=2){
    ctx.font='600 '+size+'px '+FAMILY;ctx.textAlign='left';ctx.textBaseline='middle';ctx.fillStyle=color;
    for(const ch of str){ctx.fillText(ch,x,y);x+=ctx.measureText(ch).width+spacing;}
  }
  function line(ctx,x1,y1,x2,y2,color=C.line,width=1.5){
    ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.stroke();
  }
  function word(ctx,str,x,top,size,maxWidth,seconds,color,delay=0){
    const chars=Array.from(str),gap=4;
    const total=chars.reduce((a,ch)=>a+metrics(ctx,ch,size).width,0);
    if(total+gap*(chars.length-1)>maxWidth-20)size*=(maxWidth-20-gap*(chars.length-1))/total;
    const cap=metrics(ctx,str,size);let px=x;
    for(let i=0;i<chars.length;i++){
      const m=metrics(ctx,chars[i],size);
      const enter=ramp(.23+delay+i*.042,1.10+delay+i*.042,seconds);
      const exit=ramp(4.10+i*.012,4.88+i*.012,seconds);
      ctx.save();ctx.globalAlpha=enter*(1-exit);
      ctx.font='700 '+size+'px '+FAMILY;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle=color;
      ctx.fillText(chars[i],px,top+cap.ascent+18*(1-enter)-9*exit);ctx.restore();
      px+=m.width+gap;
