    const advance=m.width,cellHeight=m.ascent+m.descent+12,baseline=top+m.ascent;
    ctx.font='700 '+size+'px '+MONO;ctx.textAlign='left';ctx.textBaseline='alphabetic';ctx.fillStyle=color;
    for(let i=0;i<3;i++){
