    else if(index===1)word(ctx,'RECONCILE',148,359,174,1130,seconds,C.ink);
    else if(index===2){
      word(ctx,'CLEAR',148,307,169,1130,seconds,C.ink);
      word(ctx,'RESULTS',148,491,190,1130,seconds,C.blue,.10);
    }else word(ctx,'RECORD',148,337,236,1130,seconds,C.ink);
    const captions=['PRECISION STARTS WITH EVERY ENTRY','BRING THE DETAILS INTO AGREEMENT','CLEAR RECORDS. CONFIDENT DECISIONS.','KEEP THE RECORDS MOVING'];
    ctx.save();ctx.globalAlpha=ramp(.40,1.35,seconds)*(1-ramp(4.12,4.94,seconds));
