    tracked(ctx,captions[index],148,index===2?676:629,17,C.muted,1.6);ctx.restore();
  }
  function frame(ctx,phase){
    tracked(ctx,'PRECISION ACCOUNTING',112,103,21,C.ink,3.2);
    label(ctx,'RECORD / RECONCILE / REPORT',1808,103,16,C.muted,'right');
