    const words=['RECORD','ALIGN','RECONCILE','REPORT'];
    for(let i=0;i<4;i++){
      const x=112+i*432,p=.5+.5*Math.cos(TAU*(phase-i/4));
      label(ctx,words[i],x,977,14,C.muted);line(ctx,x,1004,x+382,1004,C.line,2);
      line(ctx,x,1004,x+55+185*p*p,1004,C.blue,3);
    }
    label(ctx,'PRECISION IN EVERY COLUMN',112,1047,13,C.muted);
    for(let i=0;i<7;i++){
      ctx.globalAlpha=.25+.75*(.5+.5*Math.cos(TAU*(phase-i/7)));
